// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/agents/LanguagesShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Languages & mic: Settings → General → Dictation, ported from the app's
 * DictationSection (src/panels/SettingsMenu.tsx), with the My languages
 * picker open (SpeechLanguagesSelect in src/ui/DictationLanguageSelect.tsx).
 * Picking languages works like the app: up to six, the first is the main
 * one, and at least one stays. Microphone input and Recognition language
 * show their choices.
 */
import { useCallback, useId, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { Check, ChevronDown, Globe } from "lucide-react";
import { FLAGS } from "./flags";
import { SelectButton, SettingsScene } from "./parts";
import { WIN_SIZE } from "../../home/Scenes";

// The languages dictation recognizes, in the app's order (src/supportedLanguages.ts).
const LANGUAGES: { code: string; label: string; country: string }[] = [
  { code: "en", label: "English", country: "US" },
  { code: "tr", label: "Turkish", country: "TR" },
  { code: "es", label: "Spanish", country: "ES" },
  { code: "pt", label: "Portuguese", country: "PT" },
  { code: "ru", label: "Russian", country: "RU" },
  { code: "de", label: "German", country: "DE" },
  { code: "fr", label: "French", country: "FR" },
  { code: "pl", label: "Polish", country: "PL" },
  { code: "uk", label: "Ukrainian", country: "UA" },
  { code: "it", label: "Italian", country: "IT" },
  { code: "nl", label: "Dutch", country: "NL" },
  { code: "sv", label: "Swedish", country: "SE" },
  { code: "cs", label: "Czech", country: "CZ" },
  { code: "ro", label: "Romanian", country: "RO" },
  { code: "el", label: "Greek", country: "GR" },
  { code: "hu", label: "Hungarian", country: "HU" },
  { code: "da", label: "Danish", country: "DK" },
  { code: "fi", label: "Finnish", country: "FI" },
  { code: "no", label: "Norwegian", country: "NO" },
  { code: "sk", label: "Slovak", country: "SK" },
  { code: "bg", label: "Bulgarian", country: "BG" },
  { code: "lv", label: "Latvian", country: "LV" },
  { code: "sl", label: "Slovenian", country: "SI" },
  { code: "hi", label: "Hindi", country: "IN" },
];
// MAX_MY_LANGUAGES (src/state/dictation.ts).
const MAX_MY_LANGUAGES = 6;
// The demo's languages, main first.
const MINE = ["en", "es"];
/* The open list may reach to 8px above the window's bottom edge (menuBox:
   room below the trigger is the window height less 13px, plus the 5px gap),
   so the card shows the window down to the canvas padding under the tiles
   (they end 10px above the window's bottom). */
const LIST_CARD_BOTTOM = WIN_SIZE.height - 5;
/* What the visitor typed in the list's search. The open list is 320px tall,
   which leaves room for nine and a half of its 28px rows: unfiltered, the
   tenth would show cut in half. The query keeps the -ish languages, the
   demo's two among them, so every row shows whole. */
const QUERY = "sh";

/** The app's LanguageFlag: an icon-sized 3x2 flag. */
function LanguageFlag({ country }: { country: string }) {
  const flag = FLAGS[country];
  if (!flag) return null;
  return (
    <svg
      viewBox={flag.viewBox}
      aria-hidden="true"
      style={{ width: 21, height: 14, borderRadius: 2, flexShrink: 0 }}
      // Static flag markup from country-flag-icons (see flags.ts).
      dangerouslySetInnerHTML={{ __html: flag.body }}
    />
  );
}

/** The app's Settings Row (src/panels/SettingsMenu.tsx). */
function Row({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) {
  return (
    <div className="set-row">
      <div className="set-label">
        <span>{label}</span>
        {hint ? <span className="set-hint">{hint}</span> : null}
      </div>
      <div className="set-control">{children}</div>
    </div>
  );
}

function Switch({ label, on }: { label: string; on: boolean }) {
  return (
    <button type="button" className={`switch ${on ? "switch-on" : ""}`} role="switch" aria-label={label} aria-checked={on}>
      <span className="switch-knob" />
    </button>
  );
}

/** The app's Segmented. */
function Segmented({ label, options, value }: { label: string; options: string[]; value: string }) {
  return (
    <div className="segmented" role="radiogroup" aria-label={label}>
      {options.map((option) => (
        <button key={option} type="button" role="radio" aria-checked={option === value} className={`segmented-option${option === value ? " segmented-on" : ""}`}>
          {option}
        </button>
      ))}
    </div>
  );
}

interface MenuBox {
  left: number;
  top: number;
  width: number;
  height: number;
}

/** Where LanguageMenu puts its list for a trigger at `rect`, in a window the scene's size. */
function menuBox(rect: { left: number; top: number; bottom: number; width: number }): MenuBox {
  const width = Math.min(Math.max(rect.width, 280), WIN_SIZE.width - 16);
  const below = WIN_SIZE.height - rect.bottom - 13;
  const above = rect.top - 13;
  const height = Math.max(80, Math.min(320, Math.max(below, above)));
  return {
    width,
    height,
    left: Math.max(8, Math.min(rect.left, WIN_SIZE.width - width - 8)),
    top: below >= height ? rect.bottom + 5 : Math.max(8, rect.top - height - 5),
  };
}

export function LanguagesShot() {
  const [values, setValues] = useState<string[]>(MINE);
  const [open, setOpen] = useState(true);
  const [active, setActive] = useState(0);
  const [box, setBox] = useState<MenuBox | null>(null);
  const button = useRef<HTMLButtonElement>(null);
  const listId = useId();
  // The order is fixed when the menu opens: the picked languages first.
  const [order, setOrder] = useState<string[]>(() => [...MINE, ...LANGUAGES.map((item) => item.code).filter((code) => !MINE.includes(code))]);

  // The trigger's place in the window, unscaled from the card: the app
  // measures it against the viewport, which is the window here.
  const measure = useCallback(() => {
    const element = button.current;
    const frame = element?.closest(".pz-window");
    if (!element || !frame) return;
    const win = frame.getBoundingClientRect();
    const scale = win.width / WIN_SIZE.width;
    const rect = element.getBoundingClientRect();
    setBox(
      menuBox({
        left: (rect.left - win.left) / scale,
        top: (rect.top - win.top) / scale,
        bottom: (rect.bottom - win.top) / scale,
        width: rect.width / scale,
      }),
    );
  }, []);
  useLayoutEffect(() => {
    if (!open) return;
    measure();
    const observer = new ResizeObserver(measure);
    if (button.current) observer.observe(button.current);
    return () => observer.disconnect();
  }, [open, measure]);

  // The app's filter: the label or code contains the query.
  const listed = [...LANGUAGES]
    .sort((a, b) => order.indexOf(a.code) - order.indexOf(b.code))
    .filter((option) => `${option.label} ${option.code}`.toLowerCase().includes(QUERY));
  const main = LANGUAGES.find((item) => item.code === values[0]);
  const names = values.map((code) => LANGUAGES.find((item) => item.code === code)?.label ?? code);
  const pick = (code: string) => {
    if (values.includes(code)) {
      if (values.length > 1) setValues(values.filter((value) => value !== code));
    } else if (values.length < MAX_MY_LANGUAGES) setValues([...values, code]);
  };
  const toggle = () => {
    if (!open) {
      setActive(0);
      setOrder([...values, ...LANGUAGES.map((item) => item.code).filter((code) => !values.includes(code))]);
    }
    setOpen(!open);
  };

  const menu =
    open && box ? (
      <div className="cselect-backdrop pzza-portal" onMouseDown={() => setOpen(false)}>
        <div
          className="cselect-menu dictation-language-menu"
          style={{
            left: box.left,
            top: box.top,
            width: box.width,
            height: box.height,
            maxHeight: box.height,
            overflow: "hidden",
            display: "flex",
            flexDirection: "column",
            boxSizing: "border-box",
          }}
          onMouseDown={(event) => event.stopPropagation()}
        >
          <input
            type="search"
            role="combobox"
            aria-label="Search my languages"
            aria-autocomplete="list"
            aria-expanded={true}
            aria-controls={listId}
            placeholder="Search languages..."
            value={QUERY}
            readOnly
            style={{
              width: "100%",
              boxSizing: "border-box",
              padding: "9px 10px",
              marginBottom: 5,
              background: "var(--surface-alt)",
              color: "var(--text)",
              border: "1px solid var(--hairline-strong)",
              borderRadius: "var(--r-sm)",
            }}
          />
          <div id={listId} role="listbox" aria-label="My languages" aria-multiselectable="true" style={{ overflowY: "auto", minHeight: 0 }}>
            {listed.map((option, index) => (
              <button
                key={option.code}
                role="option"
                aria-selected={values.includes(option.code)}
                type="button"
                tabIndex={-1}
                className={`cselect-item ${index === active ? "cselect-item-on" : ""}`}
                onMouseMove={() => setActive(index)}
                onClick={() => pick(option.code)}
              >
                <LanguageFlag country={option.country} />
                <span className="cselect-item-main">{option.label}</span>
                <span className="cselect-item-check">{values.includes(option.code) && <Check size={14} aria-hidden="true" />}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    ) : null;

  return (
    <SettingsScene backdrop="chat" section="general" page="dictation" bottom={LIST_CARD_BOTTOM} overlay={menu}>
      <div className="settings-page general-settings">
        <section className="set-section settings-section" aria-label="Voice dictation">
          <h3 className="set-title">Voice dictation</h3>
          <div className="dictation-language-setting settings-row">
            <div className="settings-row-copy">
              <span>Microphone input</span>
              <span className="set-hint">Choose an input for voice dictation on this Mac.</span>
            </div>
            <SelectButton ariaLabel="Microphone input" label="System default" />
          </div>
          <Row label="Enable dictation" hint="A microphone button appears on each terminal">
            <Switch label="Enable dictation" on />
          </Row>
          <div className="dictation-language-setting settings-row">
            <div className="settings-row-copy">
              <span>Recognition language</span>
              <span className="set-hint">Auto-detect, or choose the language you speak.</span>
            </div>
            <button type="button" className="cselect" aria-label="Dictation language: Auto-detect language" aria-haspopup="listbox" aria-expanded={false}>
              <Globe size={18} aria-hidden="true" />
              <span className="cselect-value">Auto-detect language</span>
              <ChevronDown size={14} aria-hidden="true" />
            </button>
          </div>
          <div className="dictation-language-setting settings-row">
            <div className="settings-row-copy">
              <span>My languages</span>
              <span className="set-hint">Detection picks among these, favoring the first (your main language) when unsure.</span>
            </div>
            <span style={{ display: "flex", gap: 6, alignItems: "center", minWidth: 0 }}>
              <button
                ref={button}
                type="button"
                className={`cselect ${open ? "cselect-open" : ""}`}
                aria-label={`My languages: ${names.join(", ")}`}
                aria-haspopup="listbox"
                aria-expanded={open}
                onClick={toggle}
              >
                {main ? <LanguageFlag country={main.country} /> : <Globe size={18} aria-hidden="true" />}
                <span className="cselect-value">{names.join(", ")}</span>
                <ChevronDown size={14} aria-hidden="true" />
              </button>
              <button type="button" className="btn btn-sm">
                Use the Mac&apos;s
              </button>
            </span>
          </div>
          <Row
            label="Stop after silence"
            hint="Ends dictation after 5 seconds of quiet once you have spoken. Pauses while you talk never end it; push to talk keeps its own timing."
          >
            <Segmented label="Stop after silence" options={["Off", "3 s", "5 s", "10 s"]} value="5 s" />
          </Row>
          <Row
            label="Push to talk"
            hint="Hold Option alone to dictate into the active terminal; release to stop. Typing an Option shortcut cancels it."
          >
            <Switch label="Push to talk" on />
          </Row>
          <Row label="Option key" hint="Hold to talk, or tap to start and stop.">
            <Segmented label="Push to talk mode" options={["Hold", "Tap"]} value="Hold" />
          </Row>
          <p className="set-note">One download, no subscription or API key. Audio stays on your Mac. Stopping inserts text without submitting it.</p>
        </section>
      </div>
    </SettingsScene>
  );
}
